import json
import itertools

def solve_puzzle():
    # Define houses and attributes
    houses = [1, 2]  # left to right
    Names = ['Arnold', 'Eric']
    HairColors = ['black', 'brown']
    FavoriteSports = ['basketball', 'soccer']
    Smoothies = ['desert', 'cherry']

    # Helper to get house index (0-based) of a value in a permutation list
    def idx_of(value, perm):
        return perm.index(value)

    solution = None

    # Iterate over all possible permutations for each attribute
    for names_perm in itertools.permutations(Names):
        for hair_perm in itertools.permutations(HairColors):
            for sport_perm in itertools.permutations(FavoriteSports):
                for smoothie_perm in itertools.permutations(Smoothies):
                    # Apply constraints

                    # 1. The Desert smoothie lover is Arnold.
                    if idx_of('desert', smoothie_perm) != idx_of('Arnold', names_perm):
                        continue

                    # 2. The person who has brown hair is the person who loves basketball.
                    if idx_of('brown', hair_perm) != idx_of('basketball', sport_perm):
                        continue

                    # 3. Arnold is somewhere to the left of the person who has black hair.
                    if idx_of('Arnold', names_perm) >= idx_of('black', hair_perm):
                        continue

                    # If all constraints satisfied, construct the solution
                    rows = []
                    for i, house in enumerate(houses):
                        row = [
                            str(house),
                            names_perm[i],
                            hair_perm[i],
                            sport_perm[i],
                            smoothie_perm[i],
                        ]
                        rows.append(row)

                    solution = {
                        "solution": {
                            "header": ["House", "Name", "HairColor", "FavoriteSport", "Smoothie"],
                            "rows": rows
                        }
                    }
                    # Since puzzle should have a unique solution, we can return the first found
                    return solution

    # If no solution found, return empty structure (should not happen for a valid puzzle)
    return {
        "solution": {
            "header": ["House", "Name", "HairColor", "FavoriteSport", "Smoothie"],
            "rows": []
        }
    }

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result))
